css:
.patterns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.tile {
  display: grid;
  place-items: center;
  height: 160px;
  border: 1px solid #f97316;
  border-radius: 8px;
  font-weight: 600;
}

.stripes {
  background-image: repeating-linear-gradient(45deg, #fed7aa 0 10px, #ffffff 10px 20px);
}

.dots {
  background-image: radial-gradient(circle, #f97316 3px, transparent 3.5px);
  background-size: 20px 20px;
  background-repeat: repeat;
}
